// Hand-built label art: a tea leaf with a midrib, and a citrus slice (rind, pale pith ring, flesh, segment lines).
const r2 = v => Math.round(v * 100) / 100;
function leaf(bx, by, tx, ty, w, fill, rib) {
  const dx = tx - bx, dy = ty - by, l = Math.hypot(dx, dy), nx = -dy / l * w, ny = dx / l * w;
  const mx = bx + dx * .45, my = by + dy * .45;
  const a = [r2(mx + nx * 2), r2(my + ny * 2)], b = [r2(mx - nx * 2), r2(my - ny * 2)];
  return `<path d="M${bx} ${by}Q${a[0]} ${a[1]} ${tx} ${ty}Q${b[0]} ${b[1]} ${bx} ${by}Z" fill="${fill}"/><path d="M${bx} ${by}Q${r2(mx + nx * .25)} ${r2(my + ny * .25)} ${r2(tx - dx * .08)} ${r2(ty - dy * .08)}" fill="none" stroke="${rib}" stroke-width=".5" stroke-linecap="round"/>`;
}
function slice(cx, cy, r, rot, full, [rind, pith, flesh, seg]) {
  const disc = rr => full ? `<circle r="${r2(rr)}"` : `<path d="M${r2(-rr)} 0A${r2(rr)} ${r2(rr)} 0 0 1 ${r2(rr)} 0Z"`;
  const n = full ? 8 : 5, span = full ? 360 : 180;
  const segs = Array.from({length: full ? n : n - 1}, (_, k) => {
    const ang = (180 + span / n * (k + 1)) * Math.PI / 180;
    return `M0 0L${r2(Math.cos(ang) * r * .76)} ${r2(Math.sin(ang) * r * .76)}`;
  }).join('');
  return `<g transform="translate(${cx} ${cy}) rotate(${rot})">${disc(r)} fill="${rind}"/>${disc(r * .88)} fill="${pith}"/>${disc(r * .8)} fill="${flesh}"/><path d="${segs}${full ? '' : `M${r2(-r * .8)} 0H${r2(r * .8)}`}" stroke="${seg}" stroke-width=".4" stroke-linecap="round"/></g>`;
}

